import { f32, type Plugin, type State, type System, sparse } from "../../engine";
import { type Mirror, MirrorPlugin, mirror } from "../mirror";
import { Body, PhysicsPlugin } from "../physics";
import { CHAR_VEC4, type CharacterDef, Physics } from "../physics/core";

// Character — the kinematic capsule controller (Phase 6.4), the base a higher-level controller (the
// first-person Player) composes. The Character entity IS a capsule Body (mass <= 0) whose pose the GPU
// character pass owns (collide-and-slide each fixed step). This module is the authoring + driving surface:
// the tuning component, the registration that hands every [Character, Body] to the solver, the eid-keyed
// per-frame drive (move/jump), and the swept-pose / grounded readback a follower (a camera) reads off the
// SMALL characters buffer. The solve itself is the GPU character pass in physics/step.ts; this is its
// controller layer — Player adds look + a camera on top.

/**
 * a kinematic character — a capsule {@link Body} (`mass <= 0`) swept against static geometry each fixed step
 * (collide-and-slide). Authors the walkable slope, the jump launch speed, and a per-character gravity; the
 * controller registers every `[Character, Body]` with the solver, drives it via {@link move} / {@link jump},
 * and reads {@link grounded} / {@link pose} back. The first-person {@link Player} composes this.
 *
 * @example
 * ```
 * const body = state.create();
 * state.add(body, Body); state.add(body, Character);
 * Body.shape.set(body, ShapeKind.Capsule);
 * Body.halfExtents.set(body, 0, 0.5, 0, 0.3); Body.mass.set(body, 0);
 * Character.jumpSpeed.set(body, 5);   // 0 = no jump
 * ```
 */
export const Character = {
    /** steepest walkable slope in degrees — a contact flatter than this grounds the character; steeper, it slides */
    maxSlope: sparse(f32),
    /** the launch velocity a buffered + grounded {@link jump} sets — 0 disables jumping */
    jumpSpeed: sparse(f32),
    /** per-character gravity (negative, snappier than the world for a player) — 0 = the configured world gravity */
    gravity: sparse(f32),
};

// the registration index per character eid — setMove/jump key off registration order, so the controller owns
// registration (one setCharacters over every [Character, Body]) and remembers each eid's slot.
const index = new Map<number, number>();
// the swept-pose readback (the small characters buffer; the swept pose is lane 4) — so a follower reads the
// GPU pose by eid without mirroring the eid-indexed `bodies` firehose. Lazily allocated on the first frame
// (after every warm + Mirror.reset), like the legacy Player charMirror.
let charMirror: Mirror | null = null;

// last-registered signature — re-register ONLY on change. setCharacters re-seeds vel/grounded/move, so a
// per-frame re-register would reset a character mid-step (the same warmstart-reset discipline as the constraint
// upload). FNV_BASIS = the empty-set signature, so a scene with NO [Character] entities (one driving the solver
// imperatively via Physics.step.setCharacters) never registers — the two paths don't fight.
const FNV_BASIS = 2166136261;
const fold = (h: number, v: number): number => Math.imul(h ^ (v >>> 0), 16777619);
const _sigF32 = new Float32Array(1);
const _sigU32 = new Uint32Array(_sigF32.buffer);
const sigBits = (x: number): number => {
    _sigF32[0] = x;
    return _sigU32[0];
};
let charSig = FNV_BASIS;

function signature(state: State): number {
    let h = FNV_BASIS;
    for (const eid of state.query([Character, Body])) {
        h = fold(h, eid);
        h = fold(h, sigBits(Character.maxSlope.get(eid)));
        h = fold(h, sigBits(Character.jumpSpeed.get(eid)));
        h = fold(h, sigBits(Character.gravity.get(eid)));
    }
    return h;
}

// register every [Character, Body] with the solver + rebuild the eid→index map (registration order = the
// setMove/jump slot). gravity 0 maps to undefined so the CharacterDef default (the configured world gravity)
// applies; a non-zero value is the per-character override.
function register(state: State): void {
    const step = Physics.step;
    if (!step) return;
    index.clear();
    const defs: CharacterDef[] = [];
    for (const eid of state.query([Character, Body])) {
        index.set(eid, defs.length);
        const g = Character.gravity.get(eid);
        defs.push({
            eid,
            maxSlopeDeg: Character.maxSlope.get(eid),
            jumpSpeed: Character.jumpSpeed.get(eid),
            gravity: g !== 0 ? g : undefined,
        });
    }
    step.setCharacters(defs);
}

/** push a character's per-frame horizontal move input (world x/z velocity), by body eid. Call each fixed tick
 *  it should move; a character given no input idles (gravity still pulls it down while airborne). */
export function move(eid: number, vx: number, vz: number): void {
    const i = index.get(eid);
    if (i !== undefined) Physics.step?.setMove(i, vx, vz);
}

/** request a jump for a character this tick (by body eid) — fires only if grounded or within the coyote
 *  window, consuming both so a held button can't re-fire mid-air (the controller gates it). */
export function jump(eid: number): void {
    const i = index.get(eid);
    if (i !== undefined) Physics.step?.jump(i);
}

/** read a character's swept pose into `out` (by body eid); returns false (leaving `out` untouched) until the
 *  first readback lands. The character pass copies the body's B_POS here (lane 4) so a follower (a camera)
 *  tracks the player off the SMALL characters buffer, not the eid-indexed bodies firehose. */
export function pose(eid: number, out: [number, number, number]): boolean {
    const i = index.get(eid);
    if (i === undefined || !charMirror?.snapshot) return false;
    const f = new Float32Array(charMirror.snapshot.bytes);
    const o = (i * CHAR_VEC4 + 4) * 4;
    out[0] = f[o];
    out[1] = f[o + 1];
    out[2] = f[o + 2];
    return true;
}

/** whether a character is grounded (by body eid) — the swept-step result the controller keys jump + slope
 *  hold on. Reads the grounded flag the character pass writes into the SMALL characters buffer (cfg lane);
 *  false until the first readback lands. */
export function grounded(eid: number): boolean {
    const i = index.get(eid);
    if (i === undefined || !charMirror?.snapshot) return false;
    return new Uint32Array(charMirror.snapshot.bytes)[i * CHAR_VEC4 * 4 + 2] !== 0;
}

// register characters with the solver, re-registering only when the authored set/tuning changes. Simulation
// group so it runs before the fixed StepSystem (registration before the solve reads it) and before a consumer's
// drive (Player.control, also simulation but ordered after via its Character dependency).
const CharacterSystem: System = {
    name: "character",
    group: "simulation",
    update(state: State) {
        const step = Physics.step;
        if (!step) return;
        const sig = signature(state);
        if (sig !== charSig) {
            charSig = sig;
            register(state); // setCharacters can grow `step.characters` (a new GPUBuffer), so re-mirror AFTER
            charMirror?.dispose(); // it — else the mirror flushes a destroyed buffer ("used in submit while destroyed")
            charMirror = null;
        }
        if (!charMirror) charMirror = mirror(step.characters);
    },
};

export const CharacterPlugin: Plugin = {
    name: "Character",
    components: { Character },
    systems: [CharacterSystem],
    dependencies: [PhysicsPlugin, MirrorPlugin],
    traits: {
        Character: {
            requires: [Body],
            defaults: () => ({
                maxSlope: 45,
                jumpSpeed: 0, // no jump
                gravity: 0, // = the configured world gravity
            }),
        },
    },
    dispose() {
        charMirror?.dispose();
        charMirror = null;
        index.clear();
        charSig = FNV_BASIS;
    },
};
