import { Compute, type Plugin, type State, u32 } from "../../engine";
import { readBinary, readFile } from "../../engine/runtime";
import { Color, Part } from "../../standard/part";
import { RenderPlugin } from "../../standard/render";
import type { Binding } from "../../standard/render/core";
import { Meshes, meshBounds, packMeshes, Surfaces } from "../../standard/render/core";
import { SlabPlugin, slab } from "../../standard/slab";
import { Transform } from "../../standard/transforms";
import { type Gltf, type GltfImage, type GltfScene, parse } from "./gltf";
import { albedoArray, albedoSampler } from "./image";

export type {
    Gltf,
    GltfImage,
    GltfInstance,
    GltfMaterial,
    GltfMesh,
    GltfScene,
} from "./gltf";

/**
 * per-instance material id — an index into the per-material palette (`materialData`) the textured glTF
 * surfaces read. A `slab(u32)` published as `"material"`, so a surface samples `albedo[materialData[id].layer]`.
 * The firehose seam for textures: one more per-entity GPU column, no new draws (roadmap Phase 2).
 */
export const Material = { id: slab(u32, "material") };

// the bindings every textured glTF surface declares: the instancing convention (eids + transforms) + the
// per-instance baseColorFactor (color) + the per-instance material id (material) + the per-material palette
// (materialData) + the albedo array + its sampler. `albedo[materialData[material[eid]].layer]` resolves the
// right texture per primitive entirely on the GPU, so the pack stays one drawIndirect per (surface, mesh).
const texturedBindings: Record<string, Binding> = {
    eids: { type: "storage", element: "u32" },
    transforms: { type: "storage", element: "mat4x4<f32>" },
    color: { type: "storage", element: "vec4<f32>" },
    material: { type: "storage", element: "u32" },
    materialData: { type: "storage", element: "MaterialData" },
    albedo: { type: "texture-2d-array" },
    albedoSamp: { type: "sampler" },
};

// MaterialData packs the per-material fields the surfaces read: `layer` (the deduped albedo array layer)
// + `cutoff` (the MASK alpha threshold). 16 bytes, the Phase-3 home for metallic/roughness/emissive.
// `sampleAlbedo` is the one source for the per-instance texture lookup the three variants share.
const MATERIAL_PREAMBLE = /* wgsl */ `
struct MaterialData { layer: u32, cutoff: f32, pad0: u32, pad1: u32 }

fn sampleAlbedo(eid: u32, uv: vec2<f32>) -> vec4<f32> {
    return textureSample(albedo, albedoSamp, uv, i32(materialData[material[eid]].layer));
}
`;

// register the three alpha-mode variants of the textured surface — opaque, MASK (clip cutout → holed
// shadows), BLEND (alpha). They share bindings + `sampleAlbedo`; only the blend mode + the cutout discard
// differ. Registered in GltfPlugin.initialize (before sear.warm compiles surfaces); a draw using one stays
// skipped until loadGltf publishes `albedo` / `albedoSamp` / `materialData` (sear's lazy binding resolution)
function registerSurfaces(): void {
    Surfaces.register({
        name: "gltf-albedo",
        bindings: texturedBindings,
        preamble: MATERIAL_PREAMBLE,
        fs: /* wgsl */ `
        let tex = sampleAlbedo(eid, uv);
        col = vec4<f32>(lit(tex.rgb * color[eid].rgb, worldNormal), 1.0);`,
    });
    Surfaces.register({
        name: "gltf-albedo-clip",
        blend: "clip",
        bindings: texturedBindings,
        preamble: MATERIAL_PREAMBLE,
        fs: /* wgsl */ `
        let tex = sampleAlbedo(eid, uv);
        if (tex.a * color[eid].a < materialData[material[eid]].cutoff) { discard; }
        col = vec4<f32>(lit(tex.rgb * color[eid].rgb, worldNormal), 1.0);`,
    });
    Surfaces.register({
        name: "gltf-albedo-blend",
        blend: "alpha",
        bindings: texturedBindings,
        preamble: MATERIAL_PREAMBLE,
        fs: /* wgsl */ `
        let tex = sampleAlbedo(eid, uv) * color[eid];
        col = vec4<f32>(lit(tex.rgb, worldNormal), tex.a);`,
    });
}

// GltfPlugin owns the albedo array + material palette it publishes, initialized to a 1×1 fallback at warm
// so the textured surfaces' draws resolve (and no-op, since no entity uses them yet) before loadGltf builds
// the real array — no startup "binding not published" warning, the same fallback shape sear's shadow map
// uses. loadGltf replaces them (freeing the previous behind the submit fence); dispose frees the last.
let _albedo: GPUTexture | null = null;
let _materialData: GPUBuffer | null = null;

function publishAlbedo(
    device: GPUDevice,
    albedo: GPUTexture,
    sampler: GPUSampler,
    data: GPUBuffer,
): void {
    const stale = [_albedo, _materialData];
    _albedo = albedo;
    _materialData = data;
    Compute.textures.set("albedo", albedo);
    Compute.samplers.set("albedoSamp", sampler);
    Compute.buffers.set("materialData", data);
    // free the prior resources (fallback or earlier load) behind the fence — an in-flight frame may still
    // reference them through sear's bind group (part.ts uses the same deferred-free pattern)
    if (stale.some(Boolean)) {
        device.queue.onSubmittedWorkDone().then(() => {
            for (const r of stale) r?.destroy();
        });
    }
}

// publish a 1×1×1 fallback array + an empty palette so the textured draws bind cleanly before loadGltf
function fallbackTextures(device: GPUDevice): void {
    const albedo = device.createTexture({
        label: "gltf-albedo-fallback",
        size: { width: 1, height: 1, depthOrArrayLayers: 1 },
        format: "rgba8unorm-srgb",
        usage: GPUTextureUsage.TEXTURE_BINDING,
    });
    const data = device.createBuffer({
        label: "gltf-material-data-fallback",
        size: 16,
        usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
    });
    publishAlbedo(device, albedo, albedoSampler(device), data);
}

/**
 * the glTF importer plugin — registers the textured baseColor surfaces + the per-instance {@link Material}
 * id so a loaded scene gains its albedo. Add it alongside the default plugins when importing a textured
 * glTF; {@link loadGltf} then builds the texture array + assigns materials. Geometry-only imports work
 * without it (they ride sear's solid `default` surface).
 *
 * @example
 * ```
 * plugins: [...DEFAULT_PLUGINS, GltfPlugin]
 * await loadGltf(state, "sponza/Sponza.gltf")
 * ```
 */
export const GltfPlugin: Plugin = {
    name: "Gltf",
    components: { Material },
    dependencies: [RenderPlugin, SlabPlugin],
    traits: { Material: { defaults: () => ({ id: 0 }) } },
    initialize() {
        registerSurfaces();
    },
    warm() {
        if (Compute.device) fallbackTextures(Compute.device);
    },
    dispose() {
        _albedo?.destroy();
        _materialData?.destroy();
        _albedo = null;
        _materialData = null;
    },
};

// monotonic across loads, so a second load doesn't collide mesh-registry names with the first's
let _loadId = 0;

// spawn a decoded GltfScene as Part entities — the side-effect half of the importer. Geometry packs into
// one shared vertex + index buffer pair, registered through the procedural Meshes.register path (the load
// finishes after warm, so mesh() — which only stages at warm — can't be used); each instance becomes one
// entity with the node's TRS Transform, the primitive's baseColorFactor Color, and either a textured glTF
// surface (when its material carries a baseColorTexture and `textured` built the array) or sear's solid
// `default`. The existing Part pack + cull and sear's surfaces render it.
function load(state: State, scene: GltfScene, textured: boolean): number[] {
    const device = Compute.device;
    if (!device) throw new Error("[gltf] no GPU device — call load after build()");

    // pack the unique geometries into one buffer pair so sear binds geometry once across the import
    const packed = packMeshes(scene.meshes);
    const vertices = device.createBuffer({
        label: "gltf-vertices",
        size: packed.vertices.byteLength,
        usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
    });
    device.queue.writeBuffer(vertices, 0, packed.vertices as Float32Array<ArrayBuffer>);
    const indices = device.createBuffer({
        label: "gltf-indices",
        size: packed.indices.byteLength,
        usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
    });
    device.queue.writeBuffer(indices, 0, packed.indices as Uint32Array<ArrayBuffer>);

    // register each geometry as a slice of the shared pair; the per-load id keeps names globally unique
    // across repeated loads (a duplicate name reuses the registry id and would repoint the prior load's
    // entities). bounds drive Part's cull
    const loadId = _loadId++;
    const meshIds = packed.slices.map((s, i) =>
        Meshes.register({
            name: `gltf:${loadId}:${i}`,
            vertices,
            indices,
            indexBase: s.indexBase,
            indexCount: s.indexCount,
            bounds: meshBounds(scene.meshes[i].vertices),
        }),
    );

    // surface ids for the textured variants — registered by GltfPlugin.initialize, so present by now
    const opaque = Surfaces.id("gltf-albedo");
    const clip = Surfaces.id("gltf-albedo-clip");
    const blend = Surfaces.id("gltf-albedo-blend");

    const eids: number[] = [];
    for (const inst of scene.instances) {
        const eid = state.create();
        state.add(eid, Transform);
        state.add(eid, Part);
        state.add(eid, Color);
        Transform.pos.set(eid, inst.pos[0], inst.pos[1], inst.pos[2], 0);
        Transform.rot.set(eid, inst.rot[0], inst.rot[1], inst.rot[2], inst.rot[3]);
        Transform.scale.set(eid, inst.scale[0], inst.scale[1], inst.scale[2], 0);
        Part.mesh.set(eid, meshIds[inst.mesh]);
        const c = scene.meshes[inst.mesh].color;
        Color.rgba.set(eid, c[0], c[1], c[2], c[3]);

        // a textured material routes to the matching alpha-mode surface + carries its material id; an
        // untextured material (or a geometry-only import) keeps the solid `default` surface
        const matIdx = scene.meshes[inst.mesh].material;
        const mat = matIdx >= 0 ? scene.materials[matIdx] : undefined;
        if (textured && mat?.image !== undefined) {
            const surface =
                mat.alphaMode === "MASK" ? clip : mat.alphaMode === "BLEND" ? blend : opaque;
            if (surface !== undefined) Part.surface.set(eid, surface);
            state.add(eid, Material);
            Material.id.set(eid, matIdx);
        }
        eids.push(eid);
    }
    return eids;
}

// resolve one glTF buffer entry to its bytes — a base64 data-URI or a relative path next to the .gltf
async function resolveBuffer(uri: string | undefined, dir: string): Promise<ArrayBuffer> {
    if (!uri)
        throw new Error(
            "[gltf] glb-embedded buffers not supported — load a .gltf with external .bin",
        );
    if (uri.startsWith("data:")) return dataUri(uri).bytes;
    return readBinary(dir + uri);
}

// split a `data:` URI into its mime + decoded bytes (shared by buffer + image resolution)
function dataUri(uri: string): { mime: string; bytes: ArrayBuffer } {
    const comma = uri.indexOf(",");
    const mime = uri.slice(5, comma).split(";")[0] || "application/octet-stream";
    const bin = atob(uri.slice(comma + 1));
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return { mime, bytes: bytes.buffer };
}

// the MIME for an image path, so createImageBitmap decodes the right codec (it sniffs too, but be explicit)
function imageMime(uri: string): string {
    const ext = uri.slice(uri.lastIndexOf(".") + 1).toLowerCase();
    return ext === "jpg" || ext === "jpeg"
        ? "image/jpeg"
        : ext === "png"
          ? "image/png"
          : ext === "webp"
            ? "image/webp"
            : "application/octet-stream";
}

// resolve one image source to a Blob — source-agnostic (an external uri, a data-uri, or an embedded
// bufferView), so .glb (Phase 4) drops in by feeding bufferView-sourced images without touching this
async function resolveImage(
    image: GltfImage,
    json: Gltf,
    buffers: ArrayBuffer[],
    dir: string,
): Promise<Blob> {
    if (image.uri !== undefined) {
        if (image.uri.startsWith("data:")) {
            const d = dataUri(image.uri);
            return new Blob([d.bytes], { type: d.mime });
        }
        const bytes = await readBinary(dir + image.uri);
        return new Blob([bytes], { type: imageMime(image.uri) });
    }
    if (image.bufferView !== undefined) {
        const bv = json.bufferViews![image.bufferView];
        const start = bv.byteOffset ?? 0;
        return new Blob([buffers[bv.buffer].slice(start, start + bv.byteLength)], {
            type: image.mimeType ?? "image/png",
        });
    }
    throw new Error("[gltf] image has neither uri nor bufferView");
}

// build the albedo array + sampler + per-material palette from a decoded scene, publishing them under the
// names the textured surfaces bind. Returns false (untextured scene) when no material carries a texture, so
// the loader leaves every instance on the solid default. Single textured scene at a time — the names are
// global (roadmap Phase 2 known limit)
async function buildTextures(
    device: GPUDevice,
    scene: GltfScene,
    json: Gltf,
    buffers: ArrayBuffer[],
    dir: string,
): Promise<boolean> {
    // unique images referenced by textured materials → one array layer each (dedup: shared images share a layer)
    const used = [
        ...new Set(scene.materials.flatMap((m) => (m.image !== undefined ? [m.image] : []))),
    ];
    if (used.length === 0) return false;
    const imageLayer = new Map<number, number>();
    used.forEach((img, layer) => {
        imageLayer.set(img, layer);
    });

    const blobs = await Promise.all(
        used.map((img) => resolveImage(scene.images[img], json, buffers, dir)),
    );
    const albedo = await albedoArray(device, blobs);

    // the per-material palette indexed by material id: { layer, cutoff } (16 bytes/material). A factor-only
    // material keeps layer 0 — its instances never route to a textured surface, so it's never sampled
    const palette = new ArrayBuffer(Math.max(16, scene.materials.length * 16));
    const u = new Uint32Array(palette);
    const f = new Float32Array(palette);
    scene.materials.forEach((m, i) => {
        u[i * 4] = m.image !== undefined ? imageLayer.get(m.image)! : 0;
        f[i * 4 + 1] = m.cutoff;
    });
    const buf = device.createBuffer({
        label: "gltf-material-data",
        size: palette.byteLength,
        usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
    });
    device.queue.writeBuffer(buf, 0, palette);

    // swap the fallback (or a prior load) for the real array + palette, freeing the old behind the fence
    publishAlbedo(device, albedo, albedoSampler(device), buf);
    return true;
}

/**
 * fetch + decode + spawn a `.gltf` (external `.bin` + data-URI buffers) in one call. Resolves each buffer +
 * image relative to the `.gltf`'s directory, builds the baseColor texture array (when materials carry
 * textures + {@link GltfPlugin} is loaded), and spawns one Part entity per primitive instance. `.glb` is a
 * later add on the same {@link parse} + {@link resolveImage} (source-agnostic). Returns the spawned ids.
 *
 * @example
 * await loadGltf(state, "sponza/Sponza.gltf");
 */
export async function loadGltf(state: State, url: string): Promise<number[]> {
    const json = JSON.parse(await readFile(url)) as Gltf & {
        buffers?: { uri?: string; byteLength: number }[];
    };
    const dir = url.slice(0, url.lastIndexOf("/") + 1);
    const buffers = await Promise.all((json.buffers ?? []).map((b) => resolveBuffer(b.uri, dir)));
    const scene = parse(json, buffers);
    const textured = Compute.device
        ? await buildTextures(Compute.device, scene, json, buffers, dir)
        : false;
    return load(state, scene, textured);
}
